    /// </summary>
    /// <param name="meter">The meter that owns the instrument.</param>
    /// <param name="observeValues">Called on each collection to observe the current measurements.</param>
    public static ObservableGauge<double> CreateUptime(Meter meter, Func<IEnumerable<Measurement<double>>> observeValues) =>
        meter.CreateObservableGauge(Uptime.Name, observeValues, Uptime.Unit, Uptime.Description);
}